import { useEffect, useState } from 'react';

interface ImageVariant {
  width: number;
  height: number;
  webp: string;
  jpeg: string;
}

interface ImageInfo {
  original: string;
  width: number;
  height: number;
  aspectRatio: string;
  variants: ImageVariant[];
}

export function useImageManifest() {
  const [manifest, setManifest] = useState<Record<string, ImageInfo> | null>(null);

  useEffect(() => {
    // Dynamically fetch the manifest JSON file generated by the image generation script
    fetch('/images-manifest.json')
      .then(res => res.json())
      .then((data) => {
        setManifest(data);
      }).catch(() => {
        // If manifest is not available, set empty object
        setManifest({});
        console.warn('Images manifest not found. Run: npm run images:generate');
      });
  }, []);

  return manifest;
}
